// L-56 — scripted benchmark mode + Trex-scale fixture pack + mock server (T4-7).
//
// Proof: run the benchmark harness in-test on a small fixture and assert
// the JSON report shape. The fixture here is small and synthetic (a few
// rows); the full Trex-scale pack is generated by tool/generate_trex_fixture.dart.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:plezy/services/lowend/benchmark_mode.dart';
import 'package:plezy/services/lowend/benchmark_report.dart';
import 'package:plezy/services/lowend/frame_time_collector.dart';
import 'package:plezy/services/lowend/phase_rss_sampler.dart';
import 'package:plezy/services/lowend/slow_op_log.dart';

/// Small synthetic fixture (same shape as the Trex-scale pack, 1000×
/// smaller): 12 live channels, 3 categories, 12 VOD rows, 4 series.
Map<String, Object?> smallFixture() => {
  'liveChannels': 12,
  'categories': 3,
  'vod': 12,
  'series': 4,
  'scaleNote': 'small-test-fixture — the device pack is Trex-scale (55k live / 833 cats / 199k VOD / 46k series)',
};

void main() {
  group('BenchmarkReport (L-56)', () {
    test('JSON report shape: all required keys present', () {
      final sampler = PhaseRssSampler(rssReader: () => 400 << 20);
      sampler.sample('first_frame');
      sampler.sample('guide-open');
      final slowOps = SlowOpLog(onLine: (_) {});
      slowOps.record('feed-parse', 6000, rssBeforeMb: 400, rssAfterMb: 430, maxRssMb: 450, tier: 'low');
      final window = FrameTimeWindow('guide-scroll', 16.7);
      window.collector.recordMs(10);
      window.collector.recordMs(12);

      final journey = BenchmarkJourney(
        tier: 'low',
        appVersion: '1.2.19-2.25.0',
        sampler: sampler,
        slowOpLog: slowOps,
        frameWindows: [window],
        peakRssReader: () => 450,
      );
      journey.noteStep('cold-start');
      journey.noteStep('guide-open');
      journey.noteReliefLine(
        'RELIEF rss-high rssMb=500 rssMbAfter=470 dropped=iptv-catalogs+epg src=watchdog freedMb=30',
      );
      final report = journey.finish();

      final json = report.toJson();
      for (final key in ['tier', 'appVersion', 'startedAt', 'steps', 'phaseRss', 'frameTimes', 'slowOps', 'reliefLines', 'peakRssMb', 'lmkKills', 'gates', 'verdicts', 'verdict']) {
        expect(json, containsPair(key, isNotNull), reason: 'missing key $key');
      }
      expect(json['tier'], 'low');
      expect(json['steps'], ['cold-start', 'guide-open']);
      expect((json['phaseRss'] as List).length, 4); // 2 sampler + 2 noteStep
      expect((json['slowOps'] as List).length, 1);
      expect((json['frameTimes'] as List).length, 1);
      expect((json['reliefLines'] as List).length, 1);
      expect(json['peakRssMb'], 450);
      expect(json['verdict'], 'pass'); // 450 MB cold start passes the low gate
      expect((json['verdicts'] as Map)['coldStartMaxRss'], 'pass');
    });

    test('verdict fails when the peak breaches the tier gate', () {
      final report = BenchmarkReport(
        tier: 'low',
        appVersion: '1.2.19-2.25.0',
        startedAt: DateTime.now(),
        steps: ['cold-start'],
        phaseRss: [
          {'phase': 'first_frame', 'rssMb': 499, 'maxRssMb': 499, 'at': '2026-11-15T00:00:00Z'},
        ],
        frameTimes: const [],
        slowOps: const [],
        reliefLines: const [],
        peakRssMb: 520,
        lmkKills: 0,
      );
      // Hisense today: 499 MB cold start FAILS the T1 gate (≤450 MB).
      expect(report.verdict, 'fail');
      expect(report.verdicts['coldStartMaxRss'], 'fail');
      expect(report.verdicts['fullScriptMaxRss'], 'fail');
    });

    test('any LMK kill fails the run on every tier', () {
      final report = BenchmarkReport(
        tier: 'full',
        appVersion: '1.2.19-2.25.0',
        startedAt: DateTime.now(),
        steps: const [],
        phaseRss: const [],
        frameTimes: const [],
        slowOps: const [],
        reliefLines: const [],
        peakRssMb: 500,
        lmkKills: 1,
      );
      expect(report.verdicts['lmkKills'], 'fail');
      expect(report.verdict, 'fail');
    });

    test('report round-trips through JSON', () {
      final report = BenchmarkReport(
        tier: 'standard',
        appVersion: '1.2.19-2.25.0',
        startedAt: DateTime.parse('2026-11-15T10:00:00Z'),
        steps: ['cold-start', 'guide-open'],
        phaseRss: [
          {'phase': 'first_frame', 'rssMb': 400, 'maxRssMb': 410, 'at': '2026-11-15T10:00:01Z'},
        ],
        frameTimes: [
          {'window': 'guide-scroll', 'frames': 10, 'p50Ms': 9.5, 'p95Ms': 15.5, 'p99Ms': 20.5, 'overBudget': 1, 'worstMs': 22.0, 'budgetMs': 16.7},
        ],
        slowOps: const [],
        reliefLines: const [],
        peakRssMb: 500,
        lmkKills: 0,
      );
      final decoded = jsonDecode(jsonEncode(report.toJson())) as Map<String, Object?>;
      final restored = BenchmarkReport.fromJson(decoded);
      expect(restored.tier, 'standard');
      expect(restored.verdict, report.verdict);
      expect(restored.phaseRss.length, 1);
      expect(restored.frameTimes.length, 1);
    });

    test('writeJsonFile writes a parseable file (sync I/O, test dir)', () {
      final dir = Directory.systemTemp.createTempSync('pleztv-benchmark-test-');
      addTearDown(() => dir.deleteSync(recursive: true));
      final report = BenchmarkReport(
        tier: 'low',
        appVersion: '1.2.19-2.25.0',
        startedAt: DateTime.now(),
        steps: ['cold-start'],
        phaseRss: const [],
        frameTimes: const [],
        slowOps: const [],
        reliefLines: const [],
        peakRssMb: 400,
        lmkKills: 0,
      );
      final file = report.writeJsonFile(dir);
      expect(file.existsSync(), isTrue);
      final decoded = jsonDecode(file.readAsStringSync()) as Map<String, Object?>;
      expect(decoded['tier'], 'low');
      expect(decoded['verdict'], 'pass');
    });

    test('small fixture has the Trex-scale shape, not Trex data', () {
      final fixture = smallFixture();
      expect(fixture['liveChannels'], 12);
      expect(fixture['categories'], 3);
      expect((fixture['scaleNote'] as String), contains('55k live'));
    });

    test('scripted steps are the T4 §5 journey in order', () {
      expect(BenchmarkMode.scriptedSteps, [
        'cold-start',
        'discover',
        'guide-open',
        'guide-scroll-3-screens',
        'search-star',
        'reload',
        'playback-60s',
        'background-5min',
        'foreground',
        'vod-detail',
      ]);
      expect(BenchmarkMode.scriptedSearchNeedle, 'star');
    });
  });
}
